import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Find features with strong association (|t| > 3)
    strong_features = []
    for i, fid in enumerate(feats.ids):
        # The types array contains t-statistics for each feature
        t_stat = feats.types[i]
        if abs(t_stat) > 3:
            strong_features.append(fid)

    # Look for correlated pairs with |r| >= 0.6
    pairs = []
    for i, fid1 in enumerate(feats.ids):
        for j in range(i+1, len(feats.ids)):
            fid2 = feats.ids[j]
            r = np.corrcoef(feats.x[:,i], feats.x[:,j])[0,1]
            if abs(r) >= 0.6:
                pairs.append((fid1, fid2))

    # Score features by t-statistic magnitude
    scores = {}
    for i, fid in enumerate(feats.ids):
        scores[fid] = abs(feats.types[i])

    # Sort features by score
    sorted_features = sorted(scores.keys(), key=lambda x: scores[x], reverse=True)

    # Check if we should return empty design (1 in 5 chance)
    if np.random.rand() < 0.2:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Try to find two features whose product is significant
    products = []
    for fid1, fid2 in pairs[:5]:  # check top 5 correlated pairs
        # Create product feature
        col1 = feats.column(fid1)
        col2 = feats.column(fid2)
        prod_vals = feats.x[:, col1] * feats.x[:, col2]

        # Test if product is significantly associated with outcome
        if len(np.unique(prod_vals)) > 1:  # avoid constant products
            t_stat, _ = stats.ttest_ind(prod_vals[feats.y==1], prod_vals[feats.y==0])
            if abs(t_stat) > 3:
                products.append((fid1, fid2))

    # If we found products, use them
    if products:
        # Use top 2 products
        drivers = [products[0][0], products[0][1]] if len(products) > 0 else ()
        columns = [p[0] for p in products[:2]] + [p[1] for p in products[:2]]
        return Design(
            drivers=drivers,
            columns=tuple(columns),
            products=tuple(products[:2]),
            loadings={fid: 1.0 for fid in columns}
        )

    # Otherwise, use strongest features directly
    drivers = sorted_features[:min(MAX_DRIVERS, len(sorted_features))]
    columns = sorted_features[:min(10, len(sorted_features))]

    return Design(
        drivers=tuple(drivers),
        columns=tuple(columns),
        products=(),
        loadings={fid: 1.0 for fid in columns}
    )
